"use client";

import * as React from "react";
import { cn } from "../../lib/utils.js";

/**
 * Single-question multiple-choice quiz. Renders the question + options
 * as native radio (single-select) or checkbox (multi-select) inputs;
 * after Submit, each option flips to data-state="correct|incorrect|missed"
 * so consumers can theme right / wrong / unselected-but-correct
 * differently. Pure HTML; no heavy peer.
 *
 * Headless on grading: the schema honors what the consumer passes for
 * `correct`. Reset between runs by clearing the `selectedIds` you
 * forwarded as `value` (controlled) or unmounting (uncontrolled).
 *
 * @example
 * <Quiz
 *   question="Which planets are gas giants?"
 *   selectionMode="multi"
 *   options={[
 *     { id: "j", label: "Jupiter", correct: true },
 *     { id: "v", label: "Venus" },
 *     { id: "s", label: "Saturn", correct: true, explanation: "Saturn's atmosphere is mostly hydrogen and helium." },
 *     { id: "m", label: "Mercury" },
 *   ]}
 *   onAnswer={(ids, allCorrect) => track(ids, allCorrect)}
 * />
 */
export type QuizOption = {
	id: string;
	label: React.ReactNode;
	correct?: boolean;
	explanation?: React.ReactNode;
};

export interface QuizProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "children"> {
	/** Question prompt (any ReactNode — supports rich content). */
	question: React.ReactNode;
	/** Options the learner picks from. */
	options: QuizOption[];
	/** "single" — radio inputs (one selection). "multi" — checkboxes. Default "single". */
	selectionMode?: "single" | "multi";
	/** Custom Submit button label. Default "Submit". */
	submitLabel?: string;
	/** Fired with the selected option ids and a boolean indicating whether the entire selection matches the correct set. */
	onAnswer?: (selectedIds: string[], allCorrect: boolean) => void;
}

type CellState = "correct" | "incorrect" | "missed" | "unanswered";

function Quiz({
	question,
	options,
	selectionMode = "single",
	submitLabel = "Submit",
	onAnswer,
	className,
	...rest
}: QuizProps) {
	const [selected, setSelected] = React.useState<Set<string>>(() => new Set());
	const [submitted, setSubmitted] = React.useState(false);
	const onAnswerRef = React.useRef(onAnswer);
	onAnswerRef.current = onAnswer;
	const groupName = React.useId();

	const correctIds = React.useMemo(
		() => new Set(options.filter((o) => o.correct).map((o) => o.id)),
		[options],
	);

	const allCorrect = React.useMemo(() => {
		if (selected.size !== correctIds.size) return false;
		for (const id of correctIds) if (!selected.has(id)) return false;
		return true;
	}, [selected, correctIds]);

	const stateFor = (option: QuizOption): CellState => {
		if (!submitted) return "unanswered";
		const picked = selected.has(option.id);
		const isCorrect = correctIds.has(option.id);
		if (picked && isCorrect) return "correct";
		if (picked && !isCorrect) return "incorrect";
		if (!picked && isCorrect) return "missed";
		return "unanswered";
	};

	const toggle = (id: string) => {
		// Submit is sticky: data-state always reflects the CURRENT selection
		// against the correct set, so re-picking after submit auto-updates
		// the correct/incorrect/missed indicators without clearing the
		// "I've tried this" affordance. Next Submit re-grades and re-fires
		// onAnswer with the updated selection.
		setSelected((prev) => {
			if (selectionMode === "single") return new Set([id]);
			const next = new Set(prev);
			if (next.has(id)) next.delete(id);
			else next.add(id);
			return next;
		});
	};

	const handleSubmit = () => {
		setSubmitted(true);
		onAnswerRef.current?.(Array.from(selected), allCorrect);
	};

	const canSubmit = selected.size > 0;
	const statusText = submitted
		? allCorrect
			? "Correct — well done."
			: "Some selections are incorrect or missed. Review the highlighted options."
		: "";

	return (
		<div
			{...rest}
			data-hex-quiz
			data-submitted={submitted}
			data-all-correct={submitted && allCorrect}
			className={cn("rounded-lg border bg-card p-4 text-card-foreground", className)}
		>
			<div data-hex-quiz-question className="mb-3 text-base font-medium">
				{question}
			</div>
			<div data-hex-quiz-options className="space-y-2" role={selectionMode === "single" ? "radiogroup" : "group"}>
				{options.map((option) => {
					const state = stateFor(option);
					const isPicked = selected.has(option.id);
					return (
						<div key={option.id}>
							<label
								data-hex-quiz-option
								data-state={state}
								data-picked={isPicked}
								className={cn(
									"flex cursor-pointer items-start gap-2 rounded-md border bg-background p-2 transition-colors",
									"hover:bg-muted/50",
									state === "correct" && "border-primary bg-primary/10",
									state === "incorrect" && "border-destructive bg-destructive/10",
									state === "missed" && "border-primary/60 bg-primary/5 ring-1 ring-primary/40",
								)}
							>
								<input
									type={selectionMode === "single" ? "radio" : "checkbox"}
									name={selectionMode === "single" ? groupName : undefined}
									value={option.id}
									checked={isPicked}
									onChange={() => toggle(option.id)}
									className="mt-0.5"
								/>
								<div className="flex-1">
									<div data-hex-quiz-label>{option.label}</div>
									{submitted && option.explanation && (state === "correct" || state === "incorrect" || state === "missed") ? (
										<div data-hex-quiz-explanation className="mt-1 text-xs text-muted-foreground">
											{option.explanation}
										</div>
									) : null}
								</div>
							</label>
						</div>
					);
				})}
			</div>
			<div className="mt-3 flex items-center gap-3">
				<button
					type="button"
					data-hex-quiz-submit
					disabled={!canSubmit}
					onClick={handleSubmit}
					className={cn(
						"inline-flex h-9 items-center justify-center rounded-md bg-primary px-3 text-sm font-medium text-primary-foreground transition-opacity",
						"hover:opacity-90 disabled:cursor-not-allowed disabled:opacity-50",
						"focus:outline-none focus-visible:ring-2 focus-visible:ring-ring",
					)}
				>
					{submitLabel}
				</button>
				<div data-hex-quiz-status role="status" aria-live="polite" className="text-sm text-muted-foreground">
					{statusText}
				</div>
			</div>
		</div>
	);
}

export { Quiz };

/**
 * Color conversion utilities for the HSL-triplet token format used across
 * `@hex-core/tokens` themes (`H S% L%`, e.g. `"240 5.9% 10%"` — no `hsl()`
 * wrapper, no commas).
 *
 * The triplet is the round-trip-safe serialization for Hex Core: tokens flow
 * triplet → CSS `hsl(var(--token))` → rendered color, and the ColorPicker
 * component edits triplets directly. Hex/RGB conversions are display
 * adapters, not the source of truth.
 */

/** Parsed HSL components. `h` is degrees (0–360); `s` and `l` are percentages (0–100). */
export interface HslTriplet {
	h: number;
	s: number;
	l: number;
}

/** Parsed RGB components. Each channel is 0–255. */
export interface RgbColor {
	r: number;
	g: number;
	b: number;
}

/**
 * Parse an HSL triplet string into numeric components.
 *
 * Note: malformed input silently coerces to `{0,0,0}` (pure black) rather than
 * returning an error signal. Callers that need to distinguish "user typed
 * black" from "user typed garbage" should validate the input format first.
 * `hexToHslTriplet` returns `null` for malformed hex; this asymmetry is
 * intentional — triplets feed CSS variables where any non-color value would
 * already break rendering.
 *
 * @param triplet - String in the form `"<H> <S>% <L>%"` (e.g. `"240 5.9% 10%"`).
 * @returns Numeric components, or `{0,0,0}` if the input is malformed.
 */
export function parseHslTriplet(triplet: string): HslTriplet {
	const parts = triplet.trim().split(/\s+/);
	return {
		h: Number.parseFloat(parts[0]) || 0,
		s: Number.parseFloat(parts[1]) || 0,
		l: Number.parseFloat(parts[2]) || 0,
	};
}

/**
 * Format HSL components into an HSL triplet string (the canonical token format).
 * @param hsl - Numeric components.
 * @returns Triplet in the form `"<H> <S>% <L>%"`.
 */
export function formatHslTriplet({ h, s, l }: HslTriplet): string {
	// Tolerant integer check: rgbToHsl can produce values like 5.0000000001 due
	// to float arithmetic; format those as "5" rather than "5.0".
	const round = (n: number) =>
		Math.abs(n - Math.round(n)) < 1e-6 ? `${Math.round(n)}` : n.toFixed(1);
	return `${Math.round(h)} ${round(s)}% ${round(l)}%`;
}

/**
 * Convert HSL components to RGB.
 * @param h - Hue (0–360).
 * @param s - Saturation (0–100).
 * @param l - Lightness (0–100).
 * @returns RGB channels (0–255, rounded).
 */
export function hslToRgb(h: number, s: number, l: number): RgbColor {
	const sN = s / 100;
	const lN = l / 100;
	const k = (n: number) => (n + h / 30) % 12;
	const a = sN * Math.min(lN, 1 - lN);
	const f = (n: number) => lN - a * Math.max(-1, Math.min(k(n) - 3, 9 - k(n), 1));
	return {
		r: Math.round(255 * f(0)),
		g: Math.round(255 * f(8)),
		b: Math.round(255 * f(4)),
	};
}

/**
 * Convert RGB components to HSL.
 * @param r - Red (0–255).
 * @param g - Green (0–255).
 * @param b - Blue (0–255).
 * @returns HSL components (h: 0–360, s: 0–100, l: 0–100).
 */
export function rgbToHsl(r: number, g: number, b: number): HslTriplet {
	const rN = r / 255;
	const gN = g / 255;
	const bN = b / 255;
	const max = Math.max(rN, gN, bN);
	const min = Math.min(rN, gN, bN);
	let h = 0;
	let s = 0;
	const l = (max + min) / 2;
	if (max !== min) {
		const d = max - min;
		s = l > 0.5 ? d / (2 - max - min) : d / (max + min);
		if (max === rN) h = (gN - bN) / d + (gN < bN ? 6 : 0);
		else if (max === gN) h = (bN - rN) / d + 2;
		else h = (rN - gN) / d + 4;
		h /= 6;
	}
	return { h: h * 360, s: s * 100, l: l * 100 };
}

/**
 * Convert an HSL triplet to a 6-digit hex string.
 * @param triplet - HSL triplet (e.g. `"240 5.9% 10%"`).
 * @returns Lowercase hex string with leading `#` (e.g. `"#181a1f"`).
 */
export function hslTripletToHex(triplet: string): string {
	const { h, s, l } = parseHslTriplet(triplet);
	const { r, g, b } = hslToRgb(h, s, l);
	const toHex = (n: number) => n.toString(16).padStart(2, "0");
	return `#${toHex(r)}${toHex(g)}${toHex(b)}`;
}

/**
 * Convert a hex string to an HSL triplet.
 * Accepts 3-digit (`#abc`) or 6-digit (`#aabbcc`) hex with optional `#`.
 * @param hex - Hex color string.
 * @returns HSL triplet, or `null` if the input is malformed.
 */
export function hexToHslTriplet(hex: string): string | null {
	const clean = hex.trim().replace(/^#/, "");
	let normalized: string;
	if (/^[0-9a-fA-F]{3}$/.test(clean)) {
		normalized = clean
			.split("")
			.map((c) => c + c)
			.join("");
	} else if (/^[0-9a-fA-F]{6}$/.test(clean)) {
		normalized = clean;
	} else {
		return null;
	}
	const r = Number.parseInt(normalized.slice(0, 2), 16);
	const g = Number.parseInt(normalized.slice(2, 4), 16);
	const b = Number.parseInt(normalized.slice(4, 6), 16);
	return formatHslTriplet(rgbToHsl(r, g, b));
}

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

/**
 * Merge class names with Tailwind CSS conflict resolution.
 * @param inputs - Class values (strings, arrays, objects) to merge
 * @returns A single merged class string with Tailwind conflicts resolved
 */
export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

const SAFE_URL_SCHEMES = ["http:", "https:", "mailto:"] as const;

/**
 * Allowlist a URL for use as an `<a href>` against untrusted input.
 *
 * Returns the raw string when it's `http(s):` / `mailto:` / a relative
 * URL (no scheme); returns `undefined` otherwise. Defends against
 * `javascript:` / `data:` / `vbscript:` injection from streamed model
 * output or third-party JSON payloads that flow into citation chips.
 *
 * Inside a Markdown render path, `rehype-sanitize` already strips
 * `javascript:` from inline-link hrefs — but it does NOT introspect
 * JSON nested inside attribute values (e.g. `<sources data='[…]'/>`),
 * so the components that consume that data must guard themselves.
 *
 * @param raw - The candidate URL, or `undefined` when none was supplied.
 * @returns The URL when safe to render, otherwise `undefined`.
 */
export function safeUrl(raw: string | undefined): string | undefined {
	if (raw === undefined || raw === "") return undefined;
	// Relative URLs have no scheme — `new URL(relative)` throws without a base,
	// so a thrown URL means either malformed input OR a relative path. Treat
	// "throws + does not contain a colon" as a relative path (safe).
	let parsed: URL;
	try {
		parsed = new URL(raw);
	} catch {
		return raw.includes(":") ? undefined : raw;
	}
	return SAFE_URL_SCHEMES.some((scheme) => scheme === parsed.protocol) ? raw : undefined;
}
